code_example:
#include <iostream>
#include <utility>

template<std::size_t... Indices>
void process_array(std::index_sequence<Indices...>) {
    constexpr int arr[] = {0, 1, 2, 3, 4};  // Compile-time array
    ((std::cout << "Element at index " << Indices << ": " << arr[Indices] << std::endl), ...);
}

int main() {
    process_array(std::make_index_sequence<5>{});  // Generates std::index_sequence<0, 1, 2, 3, 4>
    return 0;
}
